#include <cstdint>
#include <string>
#include <vector>

struct Decision { std::string status; std::uint32_t bytes; };

constexpr std::uint32_t kRecordSize{ 24 };
constexpr std::uint32_t kRecordCount{ 100 };

Decision validate(const std::vector<std::uint8_t>& input, std::uint32_t inputLength, std::uint32_t outputLength)
{
    if (inputLength < 8 || input.size() < 8) return { "STATUS_BUFFER_TOO_SMALL", 0 };
    auto read32 = [&](std::size_t at) { return static_cast<std::uint32_t>(input[at]) | (static_cast<std::uint32_t>(input[at + 1]) << 8)
                                             | (static_cast<std::uint32_t>(input[at + 2]) << 16) | (static_cast<std::uint32_t>(input[at + 3]) << 24); };
    const std::uint32_t first{ read32(0) };
    const std::uint32_t count{ read32(4) };
    if (count == 0) return { "STATUS_INVALID_PARAMETER", 0 };
    if (first > kRecordCount || count > kRecordCount - first) return { "STATUS_INVALID_PARAMETER", 0 };   // no overflow
    const std::uint32_t needed{ count * kRecordSize };    // count <= 100, so this cannot overflow
    if (outputLength < needed) return { "STATUS_BUFFER_TOO_SMALL", 0 };
    return { "STATUS_SUCCESS", needed };
}

