static std::vector<std::uint8_t> request(std::uint32_t first, std::uint32_t count)
{
    std::vector<std::uint8_t> b;
    for (std::uint32_t v : { first, count }) for (int i{ 0 }; i < 4; ++i) b.push_back(static_cast<std::uint8_t>(v >> (8 * i)));
    return b;
}
TEST("a good request") { const Decision d{ validate(request(10, 5), 8, 120) }; CHECK_EQ(d.status, std::string("STATUS_SUCCESS")); CHECK_EQ(d.bytes, 120u); }
TEST("the last records") { CHECK_EQ(validate(request(90, 10), 8, 240).status, std::string("STATUS_SUCCESS")); }
TEST("input too short") { const Decision d{ validate(request(0, 1), 4, 100) }; CHECK_EQ(d.status, std::string("STATUS_BUFFER_TOO_SMALL")); CHECK_EQ(d.bytes, 0u); }
TEST("zero records") { CHECK_EQ(validate(request(0, 0), 8, 100).status, std::string("STATUS_INVALID_PARAMETER")); }
TEST("past the end") { CHECK_EQ(validate(request(95, 6), 8, 1000).status, std::string("STATUS_INVALID_PARAMETER")); CHECK_EQ(validate(request(100, 1), 8, 1000).status, std::string("STATUS_INVALID_PARAMETER")); }
TEST("overflow does not slip through") { CHECK_EQ(validate(request(0xFFFFFFF0u, 0x20), 8, 0xFFFFFFFFu).status, std::string("STATUS_INVALID_PARAMETER")); }
TEST("output too small") { const Decision d{ validate(request(0, 5), 8, 119) }; CHECK_EQ(d.status, std::string("STATUS_BUFFER_TOO_SMALL")); CHECK_EQ(d.bytes, 0u); }
TEST("a larger output buffer reports only what is written") { CHECK_EQ(validate(request(0, 2), 8, 4096).bytes, 48u); }

